PUBLIC MprJson *mprLookupJsonObj(MprJson *obj, cchar *name)
{
    MprJson      *child;
    int         i, index;

    if (!obj || !name) {
        return 0;
    }
    if (obj->type & MPR_JSON_OBJ) {
        for (ITERATE_JSON(obj, child, i)) {
            if (smatch(child->name, name)) {
                return child;
            }
        }
    } else if (obj->type & MPR_JSON_ARRAY) {
        if (*name == '$') {
            return 0;
        }
        index = (int) stoi(name);
        for (ITERATE_JSON(obj, child, i)) {
            if (i == index) {
                return child;
            }
        }
    }
    return 0;
}

