}

static MprJson *queryRange(MprJson *obj, char *property, cchar *rest, MprJson *value, int flags)
{
    MprJson     *child, *result;
    ssize       start, end;
    char        *e, *s, ibuf[16];
    int         index;

    result = mprCreateJson(MPR_JSON_ARRAY);
    if (!(obj->type & MPR_JSON_ARRAY)) {
        return result;
    }
    s = stok(property, ": \t", &e);
    start = (ssize) stoi(s);
    end = (ssize) stoi(e);
    if (start < 0) {
        start = obj->length + start;
    }
    if (end < 0) {
        end = obj->length + end;
    }
    for (ITERATE_JSON(obj, child, index)) {
        if (index < start) continue;
        if (index > end) break;
        if (rest == 0) {
            if (flags & MPR_JSON_REMOVE) {
                appendItem(result, mprRemoveJsonChild(obj, child));
            } else {
                appendItem(result, queryLeaf(obj, itosbuf(ibuf, sizeof(ibuf), index, 10), value, flags));
            }
        } else {
            appendItems(result, queryCore(child, rest, value, flags));
        }
    }
    return result;
}

static void parseAll(HttpRoute *route, cchar *key, MprJson *prop)
{
    MprJson     *routes;
    MprJson     *child;
    int         ji;

    for (ITERATE_CONFIG(route, prop, child, ji)) {
        parseKey(route, key, child);
    }

    if ((routes = mprGetJsonObj(prop, "routes")) != 0) {
        parseRoutes(route, key, routes);
    }
}

static void set_fdc(int drive)
{
	if (drive >= 0 && drive < N_DRIVE) {
		fdc = FDC(drive);
		current_drive = drive;
	}
	if (fdc != 1 && fdc != 0) {
		pr_info("bad fdc value\n");
		return;
	}
	set_dor(fdc, ~0, 8);
#if N_FDC > 1
	set_dor(1 - fdc, ~8, 0);
#endif
	if (FDCS->rawcmd == 2)
		reset_fdc_info(1);
	if (fd_inb(FD_STATUS) != STATUS_READY)
		FDCS->reset = 1;
}

bittok2str_internal(register const struct tok *lp, register const char *fmt,
	   register u_int v, const char *sep)
{
        static char buf[256]; 
        int buflen=0;
        register u_int rotbit; 
        register u_int tokval;
        const char * sepstr = "";

	while (lp != NULL && lp->s != NULL) {
            tokval=lp->v;   
            rotbit=1;
            while (rotbit != 0) {
		if (tokval == (v&rotbit)) {
                    buflen+=snprintf(buf+buflen, sizeof(buf)-buflen, "%s%s",
                                     sepstr, lp->s);
                    sepstr = sep;
                    break;
                }
                rotbit=rotbit<<1; 
            }
            lp++;
	}

        if (buflen == 0)
            (void)snprintf(buf, sizeof(buf), fmt == NULL ? "#%08x" : fmt, v);
        return (buf);
}

