static bool matchExpression(MprJson *obj, int operator, char *value)
{
    if (!(obj->type & MPR_JSON_VALUE)) {
        return 0;
    }
    value = stok(value, "'\"", NULL);
    switch (operator) {
    case JSON_OP_EQ:
        return smatch(obj->value, value);
    case JSON_OP_NE:
        return !smatch(obj->value, value);
    case JSON_OP_LT:
        return scmp(obj->value, value) < 0;
    case JSON_OP_LE:
        return scmp(obj->value, value) <= 0;
    case JSON_OP_GT:
        return scmp(obj->value, value) > 0;
    case JSON_OP_GE:
        return scmp(obj->value, value) >= 0;
    case JSON_OP_MATCH:
        return scontains(obj->value, value) != 0;
    case JSON_OP_NMATCH:
        return scontains(obj->value, value) == 0;
    default:
        return 0;
    }
}

int utf8s_to_utf16s(const u8 *s, int len, wchar_t *pwcs)
{
	u16 *op;
	int size;
	unicode_t u;

	op = pwcs;
	while (*s && len > 0) {
		if (*s & 0x80) {
			size = utf8_to_utf32(s, len, &u);
			if (size < 0)
				return -EINVAL;

			if (u >= PLANE_SIZE) {
				u -= PLANE_SIZE;
				*op++ = (wchar_t) (SURROGATE_PAIR |
						((u >> 10) & SURROGATE_BITS));
				*op++ = (wchar_t) (SURROGATE_PAIR |
						SURROGATE_LOW |
						(u & SURROGATE_BITS));
			} else {
				*op++ = (wchar_t) u;
			}
			s += size;
			len -= size;
		} else {
			*op++ = *s++;
			len--;
		}
	}
	return op - pwcs;
}

